def load_torch_checkpoint(path: Path, device: torch.device) -> Dict:
    import pathlib as _pathlib
    import os as _os
    import sys as _sys

    if _os.name == "nt":
        _pathlib.PosixPath = _pathlib.WindowsPath
    else:
        _pathlib.WindowsPath = _pathlib.PosixPath
    _sys.modules.setdefault("pathlib._local", _pathlib)
    setattr(_pathlib, "_local", _pathlib)
    try:
        return torch.load(path, map_location=device, weights_only=False)
    except TypeError:
        return torch.load(path, map_location=device)


