def counterfactual_candidate_pool_guard_aux_diagnostics(aux: Dict | None) -> Dict[str, float]:
    stats = {key: 0.0 for key in COUNTERFACTUAL_CANDIDATE_POOL_GUARD_AUX_DIAGNOSTIC_KEYS}
    if not isinstance(aux, dict):
        return stats
    control_mask = aux.get("candidate_control_family_mask")
    control_mask = control_mask.detach().to(dtype=torch.bool) if torch.is_tensor(control_mask) and control_mask.ndim == 2 else None

    def finite_reduce(values, reduction: str = "mean", mask=None) -> float:
        if not torch.is_tensor(values):
            return 0.0
        tensor = values.detach().to(dtype=torch.float32)
        if mask is not None and tuple(mask.shape) == tuple(tensor.shape):
            tensor = tensor.masked_fill(~mask.to(device=tensor.device), float("nan"))
        finite = torch.isfinite(tensor)
        if not bool(finite.any().item()):
            return 0.0
        selected = tensor[finite]
        if reduction == "max":
            return float(selected.max().item())
        if reduction == "min":
            return float(selected.min().item())
        return float(selected.mean().item())

    def candidate_stat(name: str, key: str, reduction: str = "mean") -> None:
        values = aux.get(key)
        mask = None
        if torch.is_tensor(values) and control_mask is not None and values.ndim == 2:
            mask = control_mask[: values.shape[0], : values.shape[1]]
        stats[name] = finite_reduce(values, reduction=reduction, mask=mask)

    candidate_stat("counterfactual_candidate_pool_guard_aux_control_local_delta_mean", "candidate_local_proposal_delta_magnitude")
    candidate_stat("counterfactual_candidate_pool_guard_aux_control_local_delta_max", "candidate_local_proposal_delta_magnitude", "max")
    candidate_stat("counterfactual_candidate_pool_guard_aux_control_edit_magnitude_mean", "candidate_edit_magnitude_vs_base")
    candidate_stat("counterfactual_candidate_pool_guard_aux_control_target_effect_mean", "candidate_target_effect_feature")
    candidate_stat("counterfactual_candidate_pool_guard_aux_control_target_effect_max", "candidate_target_effect_feature", "max")
    candidate_stat("counterfactual_candidate_pool_guard_aux_control_reference_distance_delta_mean", "candidate_reference_distance_delta")
    candidate_stat("counterfactual_candidate_pool_guard_aux_control_reference_distance_delta_min", "candidate_reference_distance_delta", "min")
    candidate_stat(
        "counterfactual_candidate_pool_guard_aux_control_reference_distance_improvement_mean",
        "candidate_reference_distance_improvement",
    )
    candidate_stat(
        "counterfactual_candidate_pool_guard_aux_control_reference_distance_improvement_max",
        "candidate_reference_distance_improvement",
        "max",
    )

    feature_std = aux.get("candidate_control_feature_std")
    if isinstance(feature_std, dict):
        stats["counterfactual_candidate_pool_guard_aux_control_feature_target_effect_std"] = finite_reduce(feature_std.get("target_effect"))
        stats["counterfactual_candidate_pool_guard_aux_control_feature_reference_distance_delta_std"] = finite_reduce(feature_std.get("reference_distance_delta"))
        stats["counterfactual_candidate_pool_guard_aux_control_feature_reference_distance_improvement_std"] = finite_reduce(feature_std.get("reference_distance_improvement"))
        stats["counterfactual_candidate_pool_guard_aux_control_feature_edit_magnitude_vs_base_std"] = finite_reduce(feature_std.get("edit_magnitude_vs_base"))

    pairwise_max = {}
    for source_key, name in {
        "control_candidate_pairwise_max_geom_diff_pre_compose": "pre_compose",
        "control_candidate_pairwise_max_geom_diff_post_compose": "post_compose",
        "control_candidate_pairwise_max_geom_diff_selection": "selection",
    }.items():
        values = aux.get(source_key)
        if torch.is_tensor(values) and values.ndim == 3 and values.shape[1] == values.shape[2]:
            offdiag = ~torch.eye(values.shape[1], device=values.device, dtype=torch.bool)
            masked = values.detach().to(dtype=torch.float32).masked_fill(~offdiag.view(1, values.shape[1], values.shape[2]), float("nan"))
            stats[f"counterfactual_candidate_pool_guard_aux_pairwise_{name}_mean"] = finite_reduce(masked)
            stats[f"counterfactual_candidate_pool_guard_aux_pairwise_{name}_max"] = finite_reduce(masked, "max")
            pairwise_max[name] = stats[f"counterfactual_candidate_pool_guard_aux_pairwise_{name}_max"]
    if pairwise_max.get("pre_compose", 0.0) > 1e-8:
        stats["counterfactual_candidate_pool_guard_aux_pairwise_post_to_pre_max_ratio"] = pairwise_max.get("post_compose", 0.0) / max(pairwise_max["pre_compose"], 1e-8)
    if pairwise_max.get("post_compose", 0.0) > 1e-8:
        stats["counterfactual_candidate_pool_guard_aux_pairwise_selection_to_post_max_ratio"] = pairwise_max.get("selection", 0.0) / max(pairwise_max["post_compose"], 1e-8)
    reference_l2t_diag = aux.get("reference_loose_to_tight_act_diagnostics")
    if isinstance(reference_l2t_diag, dict):
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_reference_field_batch_count"] = finite_reduce(
            reference_l2t_diag.get("reference_field_batch_count")
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_batch_count"] = finite_reduce(
            reference_l2t_diag.get("loose_to_tight_batch_count")
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_control_valid_count"] = finite_reduce(
            reference_l2t_diag.get("control_valid_count")
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_base_ref_mean"] = finite_reduce(
            reference_l2t_diag.get("base_reference_distance")
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_candidate_ref_mean"] = finite_reduce(
            reference_l2t_diag.get("candidate_reference_distance")
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_delta_mean"] = finite_reduce(
            reference_l2t_diag.get("reference_distance_delta")
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_delta_min"] = finite_reduce(
            reference_l2t_diag.get("reference_distance_delta"),
            "min",
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_delta_max"] = finite_reduce(
            reference_l2t_diag.get("reference_distance_delta"),
            "max",
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_improvement_mean"] = finite_reduce(
            reference_l2t_diag.get("reference_distance_improvement")
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_improvement_max"] = finite_reduce(
            reference_l2t_diag.get("reference_distance_improvement"),
            "max",
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_step_norm_mean"] = finite_reduce(
            reference_l2t_diag.get("step_norm")
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_step_norm_max"] = finite_reduce(
            reference_l2t_diag.get("step_norm"),
            "max",
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_target_effect_mean"] = finite_reduce(
            reference_l2t_diag.get("target_effect")
        )
        stats["counterfactual_candidate_pool_guard_aux_reference_l2t_target_effect_max"] = finite_reduce(
            reference_l2t_diag.get("target_effect"),
            "max",
        )
        for stage_name in ("pre_compose", "post_compose", "selection"):
            metric_prefix = f"counterfactual_candidate_pool_guard_aux_reference_l2t_{stage_name}"
            stats[f"{metric_prefix}_candidate_ref_mean"] = finite_reduce(
                reference_l2t_diag.get(f"{stage_name}_candidate_reference_distance")
            )
            stats[f"{metric_prefix}_delta_mean"] = finite_reduce(
                reference_l2t_diag.get(f"{stage_name}_reference_distance_delta")
            )
            stats[f"{metric_prefix}_delta_min"] = finite_reduce(
                reference_l2t_diag.get(f"{stage_name}_reference_distance_delta"),
                "min",
            )
            stats[f"{metric_prefix}_delta_max"] = finite_reduce(
                reference_l2t_diag.get(f"{stage_name}_reference_distance_delta"),
                "max",
            )
            stats[f"{metric_prefix}_improvement_mean"] = finite_reduce(
                reference_l2t_diag.get(f"{stage_name}_reference_distance_improvement")
            )
            stats[f"{metric_prefix}_improvement_max"] = finite_reduce(
                reference_l2t_diag.get(f"{stage_name}_reference_distance_improvement"),
                "max",
            )
            stats[f"{metric_prefix}_step_norm_mean"] = finite_reduce(
                reference_l2t_diag.get(f"{stage_name}_step_norm")
            )
            stats[f"{metric_prefix}_step_norm_max"] = finite_reduce(
                reference_l2t_diag.get(f"{stage_name}_step_norm"),
                "max",
            )
        pre_delta = reference_l2t_diag.get("pre_compose_reference_distance_delta")
        post_delta = reference_l2t_diag.get("post_compose_reference_distance_delta")
        selection_delta = reference_l2t_diag.get("selection_reference_distance_delta")
        if torch.is_tensor(pre_delta) and torch.is_tensor(post_delta) and tuple(pre_delta.shape) == tuple(post_delta.shape):
            stats["counterfactual_candidate_pool_guard_aux_reference_l2t_pre_to_post_delta_gap_mean"] = finite_reduce(
                post_delta - pre_delta
            )
        if (
            torch.is_tensor(post_delta)
            and torch.is_tensor(selection_delta)
            and tuple(post_delta.shape) == tuple(selection_delta.shape)
        ):
            stats["counterfactual_candidate_pool_guard_aux_reference_l2t_post_to_selection_delta_gap_mean"] = finite_reduce(
                selection_delta - post_delta
            )
        for slot_idx in range(3):
            slot_prefix = f"counterfactual_candidate_pool_guard_aux_reference_l2t_act{slot_idx}"
            stats[f"{slot_prefix}_valid_count"] = finite_reduce(
                reference_l2t_diag.get(f"act{slot_idx}_valid_count")
            )
            stats[f"{slot_prefix}_pre_delta_mean"] = finite_reduce(
                reference_l2t_diag.get(f"pre_compose_act{slot_idx}_reference_distance_delta")
            )
            stats[f"{slot_prefix}_post_delta_mean"] = finite_reduce(
                reference_l2t_diag.get(f"post_compose_act{slot_idx}_reference_distance_delta")
            )
            stats[f"{slot_prefix}_selection_delta_mean"] = finite_reduce(
                reference_l2t_diag.get(f"selection_act{slot_idx}_reference_distance_delta")
            )
            stats[f"{slot_prefix}_pre_improvement_mean"] = finite_reduce(
                reference_l2t_diag.get(f"pre_compose_act{slot_idx}_reference_distance_improvement")
            )
            stats[f"{slot_prefix}_post_improvement_mean"] = finite_reduce(
                reference_l2t_diag.get(f"post_compose_act{slot_idx}_reference_distance_improvement")
            )
            stats[f"{slot_prefix}_selection_improvement_mean"] = finite_reduce(
                reference_l2t_diag.get(f"selection_act{slot_idx}_reference_distance_improvement")
            )
            stats[f"{slot_prefix}_pre_step_norm_mean"] = finite_reduce(
                reference_l2t_diag.get(f"pre_compose_act{slot_idx}_step_norm")
            )
            stats[f"{slot_prefix}_post_step_norm_mean"] = finite_reduce(
                reference_l2t_diag.get(f"post_compose_act{slot_idx}_step_norm")
            )
    reference_inward_diag = aux.get("reference_inward_act_diagnostics")
    if isinstance(reference_inward_diag, dict):
        inward_prefix = "counterfactual_candidate_pool_guard_aux_reference_inward"
        stats[f"{inward_prefix}_reference_field_batch_count"] = finite_reduce(
            reference_inward_diag.get("reference_field_batch_count")
        )
        stats[f"{inward_prefix}_batch_count"] = finite_reduce(
            reference_inward_diag.get("inward_batch_count")
        )
        stats[f"{inward_prefix}_loose_to_tight_batch_count"] = finite_reduce(
            reference_inward_diag.get("loose_to_tight_batch_count")
        )
        stats[f"{inward_prefix}_loose_to_moderate_batch_count"] = finite_reduce(
            reference_inward_diag.get("loose_to_moderate_batch_count")
        )
        stats[f"{inward_prefix}_moderate_to_tight_batch_count"] = finite_reduce(
            reference_inward_diag.get("moderate_to_tight_batch_count")
        )
        stats[f"{inward_prefix}_control_valid_count"] = finite_reduce(
            reference_inward_diag.get("control_valid_count")
        )
        stats[f"{inward_prefix}_base_ref_mean"] = finite_reduce(
            reference_inward_diag.get("base_reference_distance")
        )
        stats[f"{inward_prefix}_candidate_ref_mean"] = finite_reduce(
            reference_inward_diag.get("candidate_reference_distance")
        )
        stats[f"{inward_prefix}_delta_mean"] = finite_reduce(
            reference_inward_diag.get("reference_distance_delta")
        )
        stats[f"{inward_prefix}_delta_min"] = finite_reduce(
            reference_inward_diag.get("reference_distance_delta"),
            "min",
        )
        stats[f"{inward_prefix}_delta_max"] = finite_reduce(
            reference_inward_diag.get("reference_distance_delta"),
            "max",
        )
        stats[f"{inward_prefix}_improvement_mean"] = finite_reduce(
            reference_inward_diag.get("reference_distance_improvement")
        )
        stats[f"{inward_prefix}_improvement_max"] = finite_reduce(
            reference_inward_diag.get("reference_distance_improvement"),
            "max",
        )
        stats[f"{inward_prefix}_step_norm_mean"] = finite_reduce(
            reference_inward_diag.get("step_norm")
        )
        stats[f"{inward_prefix}_step_norm_max"] = finite_reduce(
            reference_inward_diag.get("step_norm"),
            "max",
        )
        stats[f"{inward_prefix}_target_effect_mean"] = finite_reduce(
            reference_inward_diag.get("target_effect")
        )
        stats[f"{inward_prefix}_target_effect_max"] = finite_reduce(
            reference_inward_diag.get("target_effect"),
            "max",
        )
        for stage_name in ("pre_compose", "post_compose", "selection"):
            metric_prefix = f"{inward_prefix}_{stage_name}"
            stats[f"{metric_prefix}_candidate_ref_mean"] = finite_reduce(
                reference_inward_diag.get(f"{stage_name}_candidate_reference_distance")
            )
            stats[f"{metric_prefix}_delta_mean"] = finite_reduce(
                reference_inward_diag.get(f"{stage_name}_reference_distance_delta")
            )
            stats[f"{metric_prefix}_delta_min"] = finite_reduce(
                reference_inward_diag.get(f"{stage_name}_reference_distance_delta"),
                "min",
            )
            stats[f"{metric_prefix}_delta_max"] = finite_reduce(
                reference_inward_diag.get(f"{stage_name}_reference_distance_delta"),
                "max",
            )
            stats[f"{metric_prefix}_improvement_mean"] = finite_reduce(
                reference_inward_diag.get(f"{stage_name}_reference_distance_improvement")
            )
            stats[f"{metric_prefix}_improvement_max"] = finite_reduce(
                reference_inward_diag.get(f"{stage_name}_reference_distance_improvement"),
                "max",
            )
            stats[f"{metric_prefix}_step_norm_mean"] = finite_reduce(
                reference_inward_diag.get(f"{stage_name}_step_norm")
            )
            stats[f"{metric_prefix}_step_norm_max"] = finite_reduce(
                reference_inward_diag.get(f"{stage_name}_step_norm"),
                "max",
            )
        pre_delta = reference_inward_diag.get("pre_compose_reference_distance_delta")
        post_delta = reference_inward_diag.get("post_compose_reference_distance_delta")
        selection_delta = reference_inward_diag.get("selection_reference_distance_delta")
        if torch.is_tensor(pre_delta) and torch.is_tensor(post_delta) and tuple(pre_delta.shape) == tuple(post_delta.shape):
            stats[f"{inward_prefix}_pre_to_post_delta_gap_mean"] = finite_reduce(
                post_delta - pre_delta
            )
        if (
            torch.is_tensor(post_delta)
            and torch.is_tensor(selection_delta)
            and tuple(post_delta.shape) == tuple(selection_delta.shape)
        ):
            stats[f"{inward_prefix}_post_to_selection_delta_gap_mean"] = finite_reduce(
                selection_delta - post_delta
            )
        for slot_idx in range(3):
            slot_prefix = f"{inward_prefix}_act{slot_idx}"
            stats[f"{slot_prefix}_valid_count"] = finite_reduce(
                reference_inward_diag.get(f"act{slot_idx}_valid_count")
            )
            stats[f"{slot_prefix}_pre_delta_mean"] = finite_reduce(
                reference_inward_diag.get(f"pre_compose_act{slot_idx}_reference_distance_delta")
            )
            stats[f"{slot_prefix}_post_delta_mean"] = finite_reduce(
                reference_inward_diag.get(f"post_compose_act{slot_idx}_reference_distance_delta")
            )
            stats[f"{slot_prefix}_selection_delta_mean"] = finite_reduce(
                reference_inward_diag.get(f"selection_act{slot_idx}_reference_distance_delta")
            )
            stats[f"{slot_prefix}_pre_improvement_mean"] = finite_reduce(
                reference_inward_diag.get(f"pre_compose_act{slot_idx}_reference_distance_improvement")
            )
            stats[f"{slot_prefix}_post_improvement_mean"] = finite_reduce(
                reference_inward_diag.get(f"post_compose_act{slot_idx}_reference_distance_improvement")
            )
            stats[f"{slot_prefix}_selection_improvement_mean"] = finite_reduce(
                reference_inward_diag.get(f"selection_act{slot_idx}_reference_distance_improvement")
            )
            stats[f"{slot_prefix}_pre_step_norm_mean"] = finite_reduce(
                reference_inward_diag.get(f"pre_compose_act{slot_idx}_step_norm")
            )
            stats[f"{slot_prefix}_post_step_norm_mean"] = finite_reduce(
                reference_inward_diag.get(f"post_compose_act{slot_idx}_step_norm")
            )
    return stats


def _select_valid_batch_rows(value, valid_mask: torch.Tensor):
    if value is None or not torch.is_tensor(value):
        return value
    if value.ndim == 0 or value.shape[0] != valid_mask.shape[0]:
        return value
    return value[valid_mask.to(device=value.device, dtype=torch.bool)]


