                        target_effect_weight=args.reranker_route_control_target_effect_weight,
                        collateral_weight=args.reranker_route_control_collateral_weight,
                        label_temperature=args.reranker_route_control_temperature,
                        hard_weight=args.reranker_route_control_hard_weight,
                        pairwise_weight=args.reranker_route_control_pairwise_weight,
