            disable_structured_field_conditioning=args.disable_structured_field_conditioning,
            semantic_control_enabled=args.semantic_control_enabled,
            field_control_fields=[piece.strip() for piece in str(args.field_control_fields).split(",") if piece.strip()],
            field_control_latent_dim=args.field_control_latent_dim,
            field_control_num_act_classes=args.field_control_num_act_classes,
            local_edit_window_predictor=args.local_edit_window_predictor,
            base_preserving_selector_enabled=args.base_preserving_selector_enabled,
            selector_noncollapse_mode=args.selector_noncollapse_mode,
