                curvature_control_projection=args.curvature_control_projection,
                curvature_control_projection_strength=args.curvature_control_projection_strength,
                counterfactual_direction_residual_type=args.counterfactual_direction_residual_type,
                counterfactual_curvature_residual_type=args.counterfactual_curvature_residual_type,
                counterfactual_reference_residual_type=args.counterfactual_reference_residual_type,
                reference_control_type=args.reference_control_type,
                reference_control_strength=args.reference_control_strength,
                reference_control_apply=args.reference_control_apply,
