                reference_distance_candidate_scope=args.reference_distance_candidate_scope,
                reference_distance_candidate_mode=args.reference_distance_candidate_mode,
                counterfactual_residual_strength=args.counterfactual_residual_strength,
                counterfactual_route_frame_budget_mode=args.counterfactual_route_frame_budget_mode,
                counterfactual_route_frame_tangent_budget=args.counterfactual_route_frame_tangent_budget,
                counterfactual_route_frame_normal_budget=args.counterfactual_route_frame_normal_budget,
                counterfactual_route_frame_fields=args.counterfactual_route_frame_fields,
